def leftmostBuildingQueries(heights, queries):
    n = len(heights)
    res = [-1] * len(queries)

    # by_b[b] holds (height threshold, query index) for queries needing a building right of b
    by_b = [[] for _ in range(n)]
    for qi, (a, b) in enumerate(queries):
        if a > b:
            a, b = b, a
        if a == b or heights[a] < heights[b]:
            res[qi] = b
        else:
            by_b[b].append((heights[a], qi))

    # Monotonic stack of indices to the right of the current position:
    # heights strictly decrease from bottom to top (indices decrease too)
    stack = []
    for i in range(n - 1, -1, -1):
        for h, qi in by_b[i]:
            lo, hi, ans = 0, len(stack) - 1, -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if heights[stack[mid]] > h:
                    ans = stack[mid]   # candidate; look for one closer to the top (further left)
                    lo = mid + 1
                else:
                    hi = mid - 1
            res[qi] = ans
        while stack and heights[stack[-1]] <= heights[i]:
            stack.pop()
        stack.append(i)

    return res
